from __future__ import annotations

LOGO_LIGHT_PNG_BASE64: str = ""
LOGO_DARK_PNG_BASE64: str = ""


def _pixmap_from_base64(data: str):
    from base64 import b64decode

    from PySide6.QtCore import QByteArray
    from PySide6.QtGui import QPixmap

    if not data:
        return None
    raw = QByteArray(b64decode(data.encode("ascii")))
    pix = QPixmap()
    if pix.loadFromData(raw, "PNG") and not pix.isNull():
        return pix
    return None


def get_logo_pixmap(is_dark: bool):
    data = LOGO_DARK_PNG_BASE64 if is_dark else LOGO_LIGHT_PNG_BASE64
    return _pixmap_from_base64(data)
